(()=>{const modal=document.getElementById('previewModal');if(!modal)return;function setMode(mode){document.querySelectorAll('[data-preview-mode]').forEach(b=>b.classList.toggle('active',b.dataset.previewMode===mode));const device=document.querySelector('#previewBody .preview-device');if(device){device.classList.toggle('preview-mobile',mode==='mobile');device.classList.toggle('preview-desktop',mode!=='mobile');}}document.addEventListener('click',e=>{const button=e.target.closest('[data-preview-mode]');if(button){e.preventDefault();setMode(button.dataset.previewMode);return;}if(e.target.closest('.preview'))setTimeout(()=>setMode('desktop'),0);});new MutationObserver(()=>{if(!modal.hidden&&!document.querySelector('[data-preview-mode].active'))setMode('desktop');}).observe(modal,{attributes:true,attributeFilter:['hidden'],subtree:true,childList:true});})();